{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LOGIC_UC_B2C_B2B_RECON AS WITH lg_raw AS ( SELECT r._airbyte_data, r._airbyte_emitted_at, r._airbyte_data:\"Order_No\"::STRING AS order_no, r._airbyte_data:\"Gr_Number\"::STRING AS gr_number, TRY_TO_DATE(r._airbyte_data:\"Bill_Date\"::STRING,\'DD/MM/YYYY\') AS bill_date, r._airbyte_data:\"New_Bill_No\"::STRING AS bill_no, TRIM(r._airbyte_data:\"Branch_Code\"::STRING) AS branch_code, UPPER(TRIM(r._airbyte_data:\"Account_Name\"::STRING)) AS account_name, UPPER(COALESCE(r._airbyte_data:\"Customer_Name\"::STRING,\'\')||\' | \'||COALESCE(r._airbyte_data:\"Account_Name\"::STRING,\'\')) AS pt, LOWER(r._airbyte_data:\"Bill_Cancelled\"::STRING) AS bill_cancelled FROM SNITCH_DB.MAPLEMONK._AIRBYTE_RAW_LOGICERPNEW_GET_SALE_INVOICE r WHERE r._airbyte_emitted_at >= \'2026-07-24\' AND TRIM(r._airbyte_data:\"Branch_Code\"::STRING) IN (\'2\',\'8\',\'94\') AND TRY_TO_DATE(r._airbyte_data:\"Bill_Date\"::STRING,\'DD/MM/YYYY\') BETWEEN DATEADD(day,-1,DATE \'2026-08-01\') AND CURRENT_DATE() ), lg_hdr AS ( SELECT *, CASE WHEN pt ILIKE \'%FLIPKART INDIA PRIVATE LIMITED%\' THEN \'FLIPKART_SOR\' WHEN pt ILIKE \'%SJIT%\' THEN \'MYNTRA_SJIT\' WHEN pt ILIKE \'%MYNTRA JABONG%\' OR pt ILIKE \'%MNOW%\' OR pt ILIKE \'%M-NOW%\' THEN \'MYNTRA_NOW\' WHEN pt ILIKE \'%SPRINTPRO%\' OR pt ILIKE \'%SLIKK%\' THEN \'SLIKK\' WHEN pt ILIKE \'%INSTAMART%\' OR pt ILIKE \'%CLOUDKART%\' OR pt ILIKE \'%CLOUDSTORE%\' OR pt ILIKE \'%JUPITER KART%\' OR pt ILIKE \'%MOKSH ENTERPRISES%\' THEN \'INSTAMART\' WHEN pt ILIKE \'%BANDIDOS RETAIL LLC%\' THEN \'NOON\' WHEN pt ILIKE \'%KNOT%\' OR pt ILIKE \'%BLOCK POOL%\' THEN \'KNOT\' WHEN pt ILIKE \'%ZILO%\' THEN \'ZILO\' WHEN pt ILIKE \'%CUSTOM_CHANNEL%\' THEN \'CUSTOM\' WHEN pt ILIKE \'%TRRUU%\' OR pt ILIKE \'%ARROWHEAD%\' THEN \'B2B_CORPORATE\' END AS marketplace_group FROM lg_raw QUALIFY ROW_NUMBER() OVER (PARTITION BY order_no, bill_no ORDER BY _airbyte_emitted_at DESC) = 1 AND bill_cancelled IS DISTINCT FROM \'true\' ), lg_items AS ( SELECT h.order_no, h.gr_number, h.bill_date, h.bill_no, h.branch_code, h.account_name, h.marketplace_group, UPPER(TRIM(i.value:\"AddlItemCode\"::STRING)) AS sku, SUM(COALESCE(TRY_TO_NUMBER(i.value:\"Quantity\"::STRING),0))::NUMBER(38,0) AS logic_qty, ROUND(SUM(COALESCE(TRY_TO_NUMBER(i.value:\"Net_Amt\"::STRING),0)),2) AS logic_net_amt FROM lg_hdr h, LATERAL FLATTEN(INPUT => TRY_PARSE_JSON(h._airbyte_data:\"LstItems\"::STRING)) i WHERE NULLIF(TRIM(i.value:\"AddlItemCode\"::STRING),\'\') IS NOT NULL GROUP BY ALL ), b2c_logic AS ( SELECT order_no, gr_number, bill_date, bill_no, branch_code, account_name, sku, logic_qty FROM lg_items WHERE marketplace_group IS NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY order_no, sku ORDER BY bill_date DESC) = 1 ), b2c_inv_nf AS (SELECT DISTINCT order_no FROM b2c_logic), b2c_inv_f AS (SELECT DISTINCT gr_number FROM b2c_logic), b2c_uc AS ( SELECT dispatched_timestamp::DATE AS filter_date, marketplace_mapped, invoice_code, awb, warehouse_name, UPPER(TRIM(sku)) AS sku, COUNT(*) AS uc_qty, ROUND(SUM(selling_price),2) AS uc_value FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_INTERMEDIATE_2024 WHERE marketplace_mapped NOT LIKE \'%STORE%\' AND marketplace_mapped NOT IN (\'NOON\',\'SAPL_WH_TRANSFERS\',\'FLIPKART_SOR\',\'MYNTRA_SJIT\',\'M-NOW\',\'SLIKK\', \'M_NOW_WESTBENGAL\',\'KNOT\',\'B2B CORPORATE CHANNEL\',\'ZILO\',\'INSTAMART\',\'SNITCH HQ\',\'CUSTOM\') AND dispatched_timestamp IS NOT NULL AND dispatched_timestamp::DATE BETWEEN DATE \'2026-08-01\' AND DATEADD(day,-1,CURRENT_DATE()) AND sku NOT IN (\'DUMMY-BOX-01\') AND warehouse_name NOT ILIKE \'%surat-VRMall%\' GROUP BY ALL ), b2c AS ( SELECT \'B2C\' AS segment, u.filter_date, u.marketplace_mapped AS marketplace, u.invoice_code AS order_ref, u.invoice_code, u.awb, u.warehouse_name, u.sku, u.uc_qty, COALESCE(li.logic_qty,0) AS logic_qty, u.uc_value, CASE WHEN u.marketplace_mapped=\'FLIPKART\' AND f.gr_number IS NULL THEN \'INVOICE_MISSING\' WHEN u.marketplace_mapped<>\'FLIPKART\' AND nf.order_no IS NULL THEN \'INVOICE_MISSING\' WHEN li.sku IS NULL THEN \'ITEM_MISSING\' ELSE \'MATCHED\' END AS status, COALESCE(li.order_no, li.gr_number) AS logic_ref, li.bill_date AS logic_bill_date FROM b2c_uc u LEFT JOIN b2c_inv_nf nf ON u.marketplace_mapped<>\'FLIPKART\' AND nf.order_no = u.invoice_code LEFT JOIN b2c_inv_f f ON u.marketplace_mapped=\'FLIPKART\' AND f.gr_number = u.awb LEFT JOIN b2c_logic li ON li.sku = u.sku AND ((u.marketplace_mapped<>\'FLIPKART\' AND li.order_no = u.invoice_code) OR (u.marketplace_mapped=\'FLIPKART\' AND li.gr_number = u.awb)) ), b2b_uc AS ( SELECT CASE WHEN marketplace_mapped IN (\'M-NOW\',\'M_NOW_WESTBENGAL\') THEN \'MYNTRA_NOW\' WHEN marketplace_mapped = \'B2B CORPORATE CHANNEL\' THEN \'B2B_CORPORATE\' ELSE marketplace_mapped END AS marketplace_group, COALESCE(NULLIF(TRIM(order_name::STRING),\'\'), NULLIF(TRIM(invoice_code::STRING),\'\'), NULLIF(TRIM(awb::STRING),\'\')) AS uc_order_ref, MIN(invoice_code) AS invoice_code, MIN(awb) AS awb, MIN(dispatched_timestamp)::DATE AS filter_date, MIN(warehouse_name) AS warehouse_name, UPPER(TRIM(sku::STRING)) AS sku, COUNT(*)::NUMBER(38,0) AS uc_qty, ROUND(SUM(selling_price),2) AS uc_value FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_INTERMEDIATE_2024 WHERE marketplace_mapped IN (\'FLIPKART_SOR\',\'MYNTRA_SJIT\',\'M-NOW\',\'M_NOW_WESTBENGAL\',\'SLIKK\',\'KNOT\',\'ZILO\',\'INSTAMART\',\'NOON\',\'CUSTOM\',\'B2B CORPORATE CHANNEL\') AND dispatched_timestamp IS NOT NULL AND dispatched_timestamp::DATE BETWEEN DATE \'2026-08-01\' AND CURRENT_DATE() AND NULLIF(TRIM(sku::STRING),\'\') IS NOT NULL AND UPPER(TRIM(sku::STRING)) <> \'DUMMY-BOX-01\' AND COALESCE(warehouse_name,\'\') NOT ILIKE \'%surat-VRMall%\' GROUP BY ALL ), b2b_logic AS ( SELECT marketplace_group, COALESCE(NULLIF(TRIM(bill_no),\'\'), NULLIF(TRIM(order_no),\'\'), NULLIF(TRIM(gr_number),\'\')) AS logic_invoice_ref, bill_date, sku, SUM(logic_qty) AS logic_qty FROM lg_items WHERE marketplace_group IS NOT NULL AND bill_date >= DATE \'2026-08-01\' GROUP BY ALL ), b2b_uc_order AS (SELECT marketplace_group, uc_order_ref, SUM(uc_qty) AS uc_total_qty, COUNT(*) AS uc_sku_count FROM b2b_uc GROUP BY ALL), b2b_lg_order AS (SELECT marketplace_group, logic_invoice_ref, SUM(logic_qty) AS logic_total_qty FROM b2b_logic GROUP BY ALL), b2b_cand AS ( SELECT u.marketplace_group, u.uc_order_ref, l.logic_invoice_ref, uo.uc_total_qty, uo.uc_sku_count, lo.logic_total_qty, COUNT(*) AS overlapping_skus, SUM(LEAST(u.uc_qty, l.logic_qty)) AS matched_qty FROM b2b_uc u JOIN b2b_logic l ON l.marketplace_group=u.marketplace_group AND l.sku=u.sku JOIN b2b_uc_order uo ON uo.marketplace_group=u.marketplace_group AND uo.uc_order_ref=u.uc_order_ref JOIN b2b_lg_order lo ON lo.marketplace_group=l.marketplace_group AND lo.logic_invoice_ref=l.logic_invoice_ref GROUP BY ALL ), b2b_sel AS ( SELECT * FROM b2b_cand QUALIFY ROW_NUMBER() OVER (PARTITION BY marketplace_group, uc_order_ref ORDER BY matched_qty DESC, overlapping_skus DESC, ABS(uc_total_qty-logic_total_qty), logic_invoice_ref) = 1 AND (matched_qty/NULLIF(uc_total_qty,0) >= 0.5 OR overlapping_skus/NULLIF(uc_sku_count,0) >= 0.5) ), b2b AS ( SELECT \'B2B\' AS segment, u.filter_date, u.marketplace_group AS marketplace, u.uc_order_ref AS order_ref, u.invoice_code, u.awb, u.warehouse_name, u.sku, u.uc_qty, COALESCE(l.logic_qty,0) AS logic_qty, u.uc_value, CASE WHEN s.uc_order_ref IS NULL THEN \'INVOICE_MISSING\' WHEN l.sku IS NULL THEN \'ITEM_MISSING\' WHEN u.uc_qty > COALESCE(l.logic_qty,0) THEN \'QTY_SHORT_BILLED\' ELSE \'MATCHED\' END AS status, s.logic_invoice_ref AS logic_ref, l.bill_date AS logic_bill_date FROM b2b_uc u LEFT JOIN b2b_sel s ON s.marketplace_group=u.marketplace_group AND s.uc_order_ref=u.uc_order_ref LEFT JOIN b2b_logic l ON l.marketplace_group=s.marketplace_group AND l.logic_invoice_ref=s.logic_invoice_ref AND l.sku=u.sku ), allrows AS (SELECT * FROM b2c UNION ALL SELECT * FROM b2b) SELECT segment, filter_date, marketplace, order_ref, invoice_code, awb, warehouse_name, sku, uc_qty, logic_qty, GREATEST(uc_qty - IFF(status=\'MATCHED\', uc_qty, IFF(status=\'QTY_SHORT_BILLED\', logic_qty, 0)), 0) AS missing_qty, uc_value, ROUND(uc_value / NULLIF(uc_qty,0) * GREATEST(uc_qty - IFF(status=\'MATCHED\', uc_qty, IFF(status=\'QTY_SHORT_BILLED\', logic_qty, 0)), 0), 2) AS missing_value, status, logic_ref, logic_bill_date FROM allrows ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
